import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));

const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");

describe("review repro", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
	});
	afterEach(() => {
		if (originalParentDescriptor)
			Object.defineProperty(window, "parent", originalParentDescriptor);
	});
	it("replaces unkeyed data for a capability-only next result", async () => {
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: Object.assign(new EventTarget(), {
				location: { origin: "https://chatgpt.com" },
			}),
		});
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (
				name === "restore_lobu_app_result" &&
				args.snapshot_capability === "next-token"
			) {
				return {
					isError: false,
					structuredContent: {
						found: true,
						tool_name: "query_sdk",
						data: { title: "Next card" },
						view_state: {},
					},
				};
			}
			if (name === "save_lobu_app_state")
				return { isError: false, structuredContent: { saved: true } };
			return { isError: false, structuredContent: { found: false } };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title ?? "No result"}</span>;
		}
		render(
			<Provider devMock={{ title: "dev" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() =>
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: { globals: { toolOutput: { title: "Old unkeyed card" } } },
				}),
			),
		);
		expect(await screen.findByText("Old unkeyed card")).toBeInTheDocument();
		act(() =>
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: {
							toolOutput: {},
							toolResponseMetadata: {
								mcp_tool_result: {
									_meta: {
										"lobu/mcp-app-snapshot-capability": "next-token",
									},
								},
							},
						},
					},
				}),
			),
		);
		expect(await screen.findByText("Next card")).toBeInTheDocument();
	});
});

