		bridge.connect.mockResolvedValue(undefined);
	});
	afterEach(() => {
		if (originalParentDescriptor)
			Object.defineProperty(window, "parent", originalParentDescriptor);
	});
	it("keeps a pending capability when matching standard data arrives", async () => {
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: Object.assign(new EventTarget(), {
				location: { origin: "https://chatgpt.com" },
			}),
		});
		let resolveRestore!: (value: unknown) => void;
		const restore = new Promise((resolve) => {
			resolveRestore = resolve;
		});
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") return restore;
			if (name === "save_lobu_app_state")
				return { isError: false, structuredContent: { saved: true } };
			return { isError: false };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title ?? "No result"}</span>
					<span>open:{String(viewState["details.open"])}</span>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "dev" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() =>
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: {
							toolOutput: {},
							toolResponseMetadata: {
								mcp_tool_result: {
									_meta: {
										"lobu/mcp-app-snapshot-capability": "pending-token",
									},
								},
							},
						},
					},
				}),
			),
		);
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { snapshot_capability: "pending-token" },
			}),
		);
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "Live matching card" } });
			}
		});
		expect(await screen.findByText("Live matching card")).toBeInTheDocument();
		await act(async () => {
			resolveRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Live matching card" },
					view_state: { "details.open": true },
				},
			});
			await restore;
		});
		expect(await screen.findByText("open:true")).toBeInTheDocument();
	});
});

