import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	close: vi.fn(),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() {
			return { isError: false };
		}
	},
	PostMessageTransport: class {
		close = bridge.close;
	},
}));
const originalParentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAiDescriptor = Object.getOwnPropertyDescriptor(window, "openai");

describe("review repro", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.connect.mockResolvedValue(undefined);
	});
	afterEach(() => {
		if (originalParentDescriptor)
			Object.defineProperty(window, "parent", originalParentDescriptor);
		if (originalOpenAiDescriptor)
			Object.defineProperty(window, "openai", originalOpenAiDescriptor);
		else Reflect.deleteProperty(window, "openai");
	});
	it("keeps id-only restoration when duplicate live data arrives", async () => {
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: Object.assign(new EventTarget(), {
				location: { origin: "https://chatgpt.com" },
			}),
		});
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: { toolOutput: { title: "Same card" } },
		});
		bridge.hostContext = {
			toolInfo: { id: "same-card-id", tool: { name: "query_sdk" } },
		};
		let resolveRestore!: (value: unknown) => void;
		const restore = new Promise((resolve) => {
			resolveRestore = resolve;
		});
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") return restore;
			return { isError: false };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title ?? "No result"}</span>
					<span>open:{String(viewState["details.open"])}</span>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "dev" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { tool_call_id: "same-card-id", tool_name: "query_sdk" },
			}),
		);
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: { title: "Same card" } });
			}
		});
		await act(async () => {
			resolveRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Same card" },
					view_state: { "details.open": true },
				},
			});
			await restore;
		});
		expect(await screen.findByText("open:true")).toBeInTheDocument();
	});
});
